      "content": "**定义**:基本初等函数的导数公式是求导运算的起点,其余函数求导都由这些公式与运算法则推出。\n**核心公式与性质**:$C'=0$($C$ 为常数);$$(x^{n})'=nx^{n-1}$$ $$(\\sin x)'=\\cos x,\\quad (\\cos x)'=-\\sin x$$ $$(a^{x})'=a^{x}\\ln a\\ (a>0,\\ a\\neq 1),\\quad (e^{x})'=e^{x}$$ $$(\\log_{a}x)'=\\frac{1}{x\\ln a}\\ (a>0,\\ a\\neq 1),\\quad (\\ln x)'=\\frac{1}{x}$$ \n**方法/思路**:①先化简再求导:根式改分数指数(如 $\\sqrt{x}=x^{\\frac{1}{2}}$)、分式改负指数(如 $\\frac{1}{x}=x^{-1}$)、展开合并同类项,使各项都能套幂函数公式;②需要代值时先求导函数再代入。\n**常考题型与考法**:①选填直接求导数值或判断求导正误,命题常把 $(e^{x})'$、$(a^{x})'$、$(\\ln x)'$、$(\\log_{a}x)'$ 混排设错;②由 $f'(a)=m$ 反解参数,常与切线斜率、极值条件 $f'(x_{0})=0$ 结合;③作为一切导数题的第一步,求导错误则后续全错。\n**易错提示**:$(e^{x})'=e^{x}$,不是 $e^{x}\\cdot x$;$(a^{x})'=a^{x}\\ln a$,不是 $xa^{x-1}$;$(\\ln x)'=\\frac{1}{x}$,而 $(\\log_{a}x)'=\\frac{1}{x\\ln a}$,两者分母不同;常数导数为 0。",
