      "content": "**定义**:由基本初等函数经四则运算或复合构成的函数,用求导法则与链式法则求导。\n**核心公式与性质**:$$(u \\pm v)'=u' \\pm v'$$ $$(uv)'=u'v+uv'$$ $$\\left(\\frac{u}{v}\\right)'=\\frac{u'v-uv'}{v^{2}}\\quad (v\\neq 0)$$ 复合函数 $y=f(g(x))$:$$y'=f'(g(x))\\cdot g'(x)$$ 即由外到内逐层求导后相乘。\n**方法/思路**:①能化简先化简(展开、约分、提公因式),减少法则层数;②复合函数先分内外层:如 $y=\\sin(2x)$ 得 $y'=2\\cos(2x)$;$y=e^{x^{2}}$ 得 $y'=2xe^{x^{2}}$;$y=\\ln(3x+1)$ 得 $y'=\\frac{3}{3x+1}$;③多层复合逐层剥开处理。\n**常考题型与考法**:①综合求导后求切线、单调区间、极值——解答题流程的第一步,法则用错是主要失分点;②法则辨析:积的导数、商的导数分子顺序、链式法则是命题热点;③抽象运算:已知 $u(x_{0})$、$v(x_{0})$ 及其导数值,求 $(uv)'$、$\\left(\\frac{u}{v}\\right)'$ 在 $x_{0}$ 处的值,直接代法则。\n**易错提示**:积的导数不是 $u'v'$;商法则分母要平方 $v^{2}$,分子是 $u'v-uv'$,顺序与符号勿错;链式法则最易漏乘内层导数 $g'(x)$。",
