      "content": "**定义**:零点个数、恒成立(能成立)与不等式证明,最终都归结为\"用导数看清函数的单调性与最值\",是导数压轴题的主战场。\n**核心公式与性质**:$f(x)$ 的零点即方程 $f(x)=0$ 的实根;$f(x)\\geq a$ 恒成立 ⇔ $a\\leq \\min f(x)$;$f(x)\\leq a$ 恒成立 ⇔ $a\\geq \\max f(x)$;存在 $x$ 使 $f(x)\\geq a$ ⇔ $a\\leq \\max f(x)$;存在 $x$ 使 $f(x)\\leq a$ ⇔ $a\\geq \\min f(x)$。常用放缩:$\\ln x\\leq x-1$(等号在 $x=1$)、$e^{x}\\geq x+1$(等号在 $x=0$)。\n**方法/思路**:①零点个数:由导数确定单调区间与极值(端点)符号,画走势草图,按\"每段单调区间端点异号则恰有一个零点\"计数;②恒成立:首选分离参数(如 $a\\leq g(x)$ 恒成立则 $a\\leq \\min g(x)$),不便分离则直接分类讨论原函数;③证 $f(x)\\geq g(x)$:令 $h(x)=f(x)-g(x)$,求 $h$ 的最小值 $\\geq 0$;④能成立问题把\"存在\"转化为最大值侧的不等式。\n**常考题型与考法**:①小题:判断零点所在区间或零点个数(具体函数用单调性加端点异号);②大题恒成立求参:先分离参数再研究新函数最值,端点取等处先猜后证或用\"端点效应\"缩小参数范围再验证;③零点个数随参数变化:分离出 $a=h(x)$,数曲线 $y=h(x)$ 与水平线 $y=a$ 的交点;④不等式证明:构造差函数或按结构配对构造(含 $e^{x}$、$\\ln x$ 的式子常同乘除 $e^{x}$、$x$ 后构造),必要时引用常用放缩。\n**易错提示**:分离参数前先看分母与不等号方向;取等条件要交代;含参讨论按参数分段不重不漏;证明题须完整写出单调性与最值,不可\"显然\"带过。",
