      "content": "**定义**\n空间几何体是只考虑形状与大小抽象出的图形。由若干平面多边形围成的叫多面体:棱柱有两个面互相平行,其余各面都是四边形且相邻两四边形的公共边都互相平行;棱锥有一个面是多边形,其余各面是有一个公共顶点的三角形;棱台是用平行于棱锥底面的平面截棱锥所得的截面与底面之间的部分。旋转体由平面曲线绕定直线旋转一周围成:圆柱以矩形一边为轴,圆锥以直角三角形一直角边为轴,圆台由平行于圆锥底面的平面截圆锥而得,球由半圆以直径为轴旋转而成。\n**核心定理与公式**\n棱柱两底面平行且全等,侧面都是平行四边形,侧棱平行且相等;棱锥侧面都是三角形且有公共顶点;棱台上、下底面平行且相似,侧面为梯形,各侧棱延长线必交于一点(与一般梯形多面体的本质区别)。圆柱轴截面为矩形、圆锥为等腰三角形、圆台为等腰梯形;圆柱、圆锥母线等长,圆锥母线交于顶点。按底面边数命名三棱柱、四棱锥、三棱台等;正棱锥指底面为正多边形且顶点在底面射影为底面中心。\n**方法/思路**\n辨析几何体一律回到定义逐条核对:判断是不是棱柱看侧棱是否都平行且底面平行;判断棱台要验证“能还原成棱锥”(侧棱延长交于一点);判断旋转体看旋转轴、母线、有无顶点,底面是圆面还是圆;轴截面是把立体问题转平面的首选工具。\n**常考题型与考法**\n①简单几何体识别(举一反三8.1题型1):给图形选圆柱、棱柱等,按定义排除。②结构特征真伪判断(8.1题型2):选项式辨析,如“各侧面都是等边三角形的六棱锥不存在”(六个侧面的顶角和为360°,无法围成锥面)、“两底面平行且相似、各面为梯形的不一定是棱台”。③旋转体、组合体与平面图形旋转成体(8.1题型3~5):想清旋转轴位置,斜边绕轴旋转不成圆锥。\n**易错提示**\n有两个面互相平行、其余各面都是平行四边形的几何体不一定是棱柱(侧棱未必平行);底面是正方形的四棱柱不一定是正方体;棱台必须由棱锥截得;圆柱两底面是圆面不是圆周;球可看作到定点距离等于定长的点的集合,其截面总是圆面。",
