      "content": "**定义**\n两平面没有公共点时,称平面与平面平行,记 $\\alpha\\parallel\\beta$。\n**核心定理与公式**\n判定定理:一个平面内的两条相交直线都与另一个平面平行,则这两个平面平行(两线必须相交、同在面内)。判定推论:一个平面内两条相交直线分别平行于另一个平面内的两条相交直线,则两平面平行。性质定理:若 $\\alpha\\parallel\\beta$,第三个平面 $\\gamma$ 与它们分别交于 $a$、$b$,则 $a\\parallel b$(交线平行)。其他性质:两平行平面中,一个平面内的任意直线平行于另一个平面;夹在两平行平面间的平行线段长相等;过平面外一点有且只有一个平面与已知平面平行;两直线被三个平行平面所截,对应线段成比例。\n**方法/思路**\n转化链:线线平行→线面平行→面面平行,反方向面面平行又可推线面、线线平行。证面面平行先在一个面内找两条相交直线分别与另一面平行;正方体、长方体中常用相对面、对角面搭桥。书写顺序:①在 $\\alpha$ 内取两条相交直线 $a$、$b$;②分别证 $a\\parallel\\beta$、$b\\parallel\\beta$;③由判定定理得 $\\alpha\\parallel\\beta$。两平行平面可定义平面间距离(一个平面内任一点到另一平面的距离),常转化为点面距离用等体积法或向量法求,见“空间向量与立体几何”节点。\n**常考题型与考法**\n①面面平行判定(8.5题型3):在棱柱、棱锥中证两截面(如 $A_{1}BD$ 与 $CB_{1}D_{1}$)平行,先证两条相交线分别平行另一平面。②面面平行性质应用(8.5题型7):用两平行平面与第三平面交线平行求角度、长度。③结合线面平行性质的构造与综合应用(8.5题型8)。\n**易错提示**\n面内只有一条直线平行另一平面,或两条平行直线分别平行另一平面,都不足以判面面平行(须两条相交直线);面面平行推线线平行必须第三个平面去截,否则两平面内的直线可能异面;正方体对角面与底面不平行;证平行时先确认面与面的对应关系再写条件。",
      "links": [
        "solid-line-parallel",
        "solid-vector"
      ],
      "book": "必修二",
      "ch": "第8章 立体几何初步"
