      "content": "**定义/概念**\n以 $x$ 轴正半轴为基准,按逆时针方向旋转到直线向上方向所成的角 $\\alpha$ 叫做直线的倾斜角;与 $x$ 轴平行或重合时取 $\\alpha=0^{\\circ}$,故 $\\alpha\\in[0^{\\circ},180^{\\circ})$,左闭右开不能写成闭区间。倾斜角刻画直线方向,斜率把方向量化:当 $\\alpha\\neq90^{\\circ}$ 时 $k=\\tan\\alpha$,当 $\\alpha=90^{\\circ}$(直线垂直于 $x$ 轴)时斜率不存在。注意“斜率不存在”不等于直线不存在,此时直线形如 $x=x_{0}$,仍有倾斜角 $90^{\\circ}$。倾斜角是解析几何的起点,求方程、判断平行与垂直都先与它打交道。\n**核心公式**\n$k=\\tan\\alpha$($\\alpha\\neq90^{\\circ}$);过 $P_{1}(x_{1},y_{1})$、$P_{2}(x_{2},y_{2})$($x_{1}\\neq x_{2}$)的斜率 $k=\\frac{y_{2}-y_{1}}{x_{2}-x_{1}}$;一般式 $Ax+By+C=0$($B\\neq0$)对应 $k=-\\frac{A}{B}$,方向向量可取 $(B,-A)$,故由方向向量 $(u,v)$ 也可得 $k=\\frac{v}{u}$($u\\neq0$)。对应关系:$\\alpha=0^{\\circ}$ 时 $k=0$;$0^{\\circ}<\\alpha<90^{\\circ}$ 时 $k>0$,且 $\\alpha$ 增大 $k$ 增大;$90^{\\circ}<\\alpha<180^{\\circ}$ 时 $k<0$,且 $\\alpha$ 增大 $k$ 也增大;$\\alpha$ 越过 $90^{\\circ}$ 时斜率从 $+\\infty$“跳”到 $-\\infty$,在 $90^{\\circ}$ 处断开。\n**方法/思路**\n由斜率范围反求倾斜角范围:正切在 $[0^{\\circ},90^{\\circ})$ 与 $(90^{\\circ},180^{\\circ})$ 上分别单调递增,须把 $k\\ge0$、$k<0$ 两段分开反解再取并集,借助 $y=\\tan\\alpha$ 的图像最稳。“过定点的直线与线段 $AB$ 相交求斜率范围”:先算直线过 $A$、$B$ 两端时的临界斜率,再结合图形判断取中间还是两侧,斜率不存在的竖直线要单独检验。三点共线可转化为两条线段斜率相等,常用于验证与求点;当两直线都垂直于 $x$ 轴时斜率均不存在,其平行关系要单独判定。\n**常考题型与考法**\n①由方程或两点求斜率、倾斜角:先求 $k$,再按符号确定 $\\alpha$ 所在区间(如 $k=-1$ 得 $135^{\\circ}$);②由倾斜角或斜率范围求参数;③直线与线段相交的斜率范围:临界斜率加分类讨论再取并集;④与平行、垂直综合,应用 $k_{1}=k_{2}$、$k_{1}k_{2}=-1$;⑤借助方向向量、法向量求斜率或倾斜角;⑥由几何直观判断:倾斜角相等的直线平行,倾斜角相差 $90^{\\circ}$ 的直线垂直。\n**易错提示**\n$\\alpha=90^{\\circ}$ 表示斜率不存在而非直线不存在;由 $k<0$ 反解 $\\alpha$ 应取钝角 $90^{\\circ}<\\alpha<180^{\\circ}$,勿误取锐角;两点斜率公式要求 $x_{1}\\neq x_{2}$,横坐标相同时不能用;斜率范围跨正负(经过“无穷”)时必须分段书写,不能连成一个闭区间;两条直线斜率相等推平行时,先确认两直线不重合。",
