      "content": "**定义/概念**\n直线与圆的位置关系:相离(无公共点)、相切(1 个公共点)、相交(2 个公共点)。点与圆的位置决定过该点可作切线的条数:圆内 0 条、圆上 1 条、圆外 2 条。圆方程简单、图形对称,判定优先用几何法(圆心到直线的距离 $d$ 与半径 $r$ 比较),含参问题则常用判别式或先找直线恒过的定点。\n**核心公式**\n$d>r$ 相离,$d=r$ 相切,$d<r$ 相交;联立消元后 $\\Delta>0$、$\\Delta=0$、$\\Delta<0$ 分别对应相交、相切、相离。相交弦长 $|AB|=2\\sqrt{r^{2}-d^{2}}$($d$ 为弦心距),弦中点即圆心向弦所作垂线的垂足;用联立法也可得 $|AB|=\\sqrt{1+k^{2}}\\cdot\\frac{\\sqrt{\\Delta}}{|a|}$($\\Delta$ 为消元后判别式),两种算法等价。圆 $x^{2}+y^{2}=r^{2}$ 上点 $(x_{0},y_{0})$ 处切线:$x_{0}x+y_{0}y=r^{2}$;圆 $(x-a)^{2}+(y-b)^{2}=r^{2}$ 上点 $(x_{0},y_{0})$ 处切线:$(x_{0}-a)(x-a)+(y_{0}-b)(y-b)=r^{2}$;过圆外点 $P$ 的切线长 $|PA|=\\sqrt{|PO|^{2}-r^{2}}$。\n**方法/思路**\n过圆外一点求切线:设点斜式 $y-y_{0}=k(x-x_{0})$,由 $d=r$ 解 $k$;若 $k$ 无解说明存在垂直于 $x$ 轴的切线,必须补验 $x=x_{0}$。过圆上一点的切线也可用“半径与切线垂直”:求圆心与切点连线的斜率再取负倒数,斜率不存在时切线竖直。圆外一点到两切点的切线长相等,两切点连线(切点弦)垂直于该点与圆心的连线。已知弦长求直线:先由弦长反解 $d$ 再求参数,一般两解。\n**常考题型与考法**\n①由位置关系求参数范围:用 $d$ 与 $r$ 的大小列不等式;②切线:切线方程、切线长、切点弦;③弦长与弦中点,注意 $d^{2}+\\left(\\frac{|AB|}{2}\\right)^{2}=r^{2}$;④最值:圆上点到直线距离为 $d\\pm r$,到定点距离为 $|PO|\\pm r$;过圆内定点的最长弦为直径、最短弦垂直于该点与圆心的连线;⑤“含参直线恒过圆内点”时直接判断直线与圆恒相交;⑥求弦中点的轨迹:弦中点与圆心的连线垂直于弦,由垂直关系消去斜率参数可得轨迹方程。\n**易错提示**\n过圆外点设点斜式求切线会漏竖直线,解 $k$ 无解时务必补验 $x=x_{0}$;弦长公式中 $d$ 是圆心到直线的距离(弦心距);切线长 $|PA|=\\sqrt{|PO|^{2}-r^{2}}$ 勿丢 $-r^{2}$;与已知直线平行且与圆相切的直线有两条,应分别验证;判断“过圆上一点”与“过圆外一点”的切线条数不能混淆。",
