      "content": "**定义/概念**\n两圆位置由圆心距 $d=|O_{1}O_{2}|$ 与半径 $r_{1}\\ge r_{2}$ 的和差决定:外离 $d>r_{1}+r_{2}$;外切 $d=r_{1}+r_{2}$;相交 $|r_{1}-r_{2}|<d<r_{1}+r_{2}$;内切 $d=|r_{1}-r_{2}|$;内含 $d<|r_{1}-r_{2}|$。外切与内切统称相切,讨论须分开;同心圆 $d=0$,半径不等为内含、相等则重合。判定口诀:先算 $d$,再与 $r_{1}+r_{2}$、$|r_{1}-r_{2}|$ 比大小。外离与内含都无公共点,要靠半径和差区分,不能只看公共点个数。\n**核心公式**\n两圆 $C_{1}:x^{2}+y^{2}+D_{1}x+E_{1}y+F_{1}=0$、$C_{2}:x^{2}+y^{2}+D_{2}x+E_{2}y+F_{2}=0$ 方程相减得 $(D_{1}-D_{2})x+(E_{1}-E_{2})y+(F_{1}-F_{2})=0$:相交时是公共弦所在直线(公共弦被连心线垂直平分),相切时是公切线,相离或内含时只是等幂轴。公共弦长 $|AB|=2\\sqrt{r^{2}-d^{2}}$,其中 $d$ 为圆心到公共弦所在直线的距离。过两圆交点的圆系 $C_{1}+\\lambda C_{2}=0$($\\lambda\\neq-1$);过圆 $C$ 与直线 $l$ 交点的圆系 $C+\\lambda l=0$。\n**方法/思路**\n判定流程:配方求两圆心与半径,算 $d=|O_{1}O_{2}|$,再比较。求“过两圆交点且满足额外条件”的圆:设圆系 $C_{1}+\\lambda C_{2}=0$,代第三条件解 $\\lambda$,免解交点;该圆系不含 $C_{2}$,答案恰为 $C_{2}$ 时须单独补验。求公切线一般设 $y=kx+m$,分别用 $d=r$ 对两圆列方程,联立解 $k$、$m$;小题多只问公切线条数,可画图按位置直接数出,避免硬算。\n**常考题型与考法**\n①由位置关系反求圆心距或参数范围,分类讨论内切、外切;②公共弦方程与公共弦长:相减得直线,算弦心距再求弦长;③过两圆交点的圆的方程:圆系法;④公切线条数:外离 4、外切 3、相交 2、内切 1、内含 0;⑤圆系恒过定点即两圆交点;⑥两圆相切时圆心距与半径和差的关系式反求参数;⑦由位置关系列含参不等式组求参数范围时条件要写全,如相切要分别列 $d=r_{1}+r_{2}$ 与 $d=|r_{1}-r_{2}|$ 两种情况。\n**易错提示**\n相切包含内切、外切两类,勿漏其一;内切、内含比较的是 $|r_{1}-r_{2}|$,须加绝对值;两圆方程相减仅在相交时是公共弦,相离、内含时不能称为公共弦;圆系 $C_{1}+\\lambda C_{2}=0$ 要求 $\\lambda\\neq-1$ 且本身不含 $C_{2}$;配方求半径时注意 $D^{2}+E^{2}-4F$ 需开方前判正;半径相等的两圆不存在内切、内含,只可能是外离、外切、相交或重合;判位置前先画草图,外离与内含的图形差异一目了然。",
