      "content": "**定义/概念**\n椭圆:平面内到两定点 $F_{1}$、$F_{2}$(焦点)的距离之和等于常数 $2a$($2a>2c=|F_{1}F_{2}|$)的点的轨迹,即 $|PF_{1}|+|PF_{2}|=2a$。若 $2a=2c$ 轨迹退化为线段 $F_{1}F_{2}$,若 $2a<2c$ 无轨迹;判断时借助“三角形两边之和大于第三边”。定义式是解题第一工具,凡遇“到两焦点距离”“过焦点的弦”先回到定义。\n**核心公式**\n焦点在 $x$ 轴的标准方程 $\\frac{x^{2}}{a^{2}}+\\frac{y^{2}}{b^{2}}=1$($a>b>0$),焦点 $(\\pm c,0)$,且 $a^{2}=b^{2}+c^{2}$(即 $c^{2}=a^{2}-b^{2}$,其中 $a$ 最大);焦点在 $y$ 轴时 $x$、$y$ 对调,焦点 $(0,\\pm c)$。范围 $|x|\\le a$、$|y|\\le b$;长轴长 $2a$、短轴长 $2b$、焦距 $2c$。离心率 $e=\\frac{c}{a}=\\sqrt{1-\\frac{b^{2}}{a^{2}}}$,满足 $0<e<1$,越大椭圆越扁。焦半径(焦点在 $x$ 轴):$|PF_{1}|=a+ex_{0}$、$|PF_{2}|=a-ex_{0}$,取值范围 $a-c\\le|PF|\\le a+c$。焦点三角形周长 $2(a+c)$,面积 $S=b^{2}\\tan\\frac{\\theta}{2}$($\\theta=\\angle F_{1}PF_{2}$),点 $P$ 在短轴端点时面积最大。\n**方法/思路**\n求方程:定义法直接确定 $2a$;待定系数法——焦点位置明确就设标准式,不明确则分类讨论,或用 $mx^{2}+ny^{2}=1$($m>0$、$n>0$、$m\\neq n$)统一设。求离心率:由边长关系、焦点三角形、定义式建立关于 $a$、$c$ 的齐次式,同除以 $a^{2}$ 得 $e$ 的方程;求范围再配 $0<e<1$ 与题意。判断焦点在哪个轴:比较 $x^{2}$、$y^{2}$ 分母的大小,大分母对应长轴所在坐标轴;焦点三角形中由 $|PF_{1}|+|PF_{2}|=2a$ 与余弦定理可解出各边长与角度。\n**常考题型与考法**\n①定义求焦半径与周长:过焦点的弦 $AB$ 满足 $|AF_{2}|+|BF_{2}|=4a-|AB|$,可秒解周长类小题;②求标准方程:先判焦点在 $x$ 轴还是 $y$ 轴;③离心率求值与范围:用焦点三角形、顶点与焦点的距离关系列式;④最值:用有界性 $|x|\\le a$、$|y|\\le b$ 或参数方程 $x=a\\cos\\varphi$、$y=b\\sin\\varphi$ 化三角最值;⑤焦点三角形面积与 $\\theta$ 的关系;⑥动点轨迹:用椭圆定义判定并补全范围;⑦与直线相交的弦长、面积问题(联立韦达,见“直线与圆锥曲线”节点);⑧求焦点三角形周长直接得 $2(a+c)$,涉及过焦点弦时用定义把两段焦半径“补”成 $2a$ 再整体计算。\n**易错提示**\n几何关系是 $a^{2}=b^{2}+c^{2}$ 且 $a$ 最大,与双曲线相反;离心率恒在 $(0,1)$ 内;方程表示椭圆须两分母为正且不相等;焦点在 $y$ 轴时 $a^{2}$ 在 $y^{2}$ 的分母下、焦点 $(0,\\pm c)$;焦半径 $a\\pm ex_{0}$ 的加减对应左右焦点,勿写反;求轨迹勿忘去掉退化点。",
