      "content": "**定义/概念**\n双曲线:平面内到两定点 $F_{1}$、$F_{2}$ 的距离之差的绝对值等于常数 $2a$($0<2a<2c=|F_{1}F_{2}|$)的点的轨迹,即 $||PF_{1}|-|PF_{2}||=2a$。绝对值对应两支:差取正时点在靠近 $F_{2}$ 的一支,取负时在另一支;当 $2a=2c$ 退化为两条射线,当 $2a>2c$ 无轨迹。选择题常与椭圆定义对比考查:看“和”还是“差的绝对值”,以及常数与焦距的大小关系。\n**核心公式**\n焦点在 $x$ 轴的标准方程 $\\frac{x^{2}}{a^{2}}-\\frac{y^{2}}{b^{2}}=1$,焦点 $(\\pm c,0)$,且 $c^{2}=a^{2}+b^{2}$($c$ 最大);实轴长 $2a$、虚轴长 $2b$。渐近线 $y=\\pm\\frac{b}{a}x$(焦点在 $y$ 轴时渐近线为 $y=\\pm\\frac{a}{b}x$,注意 $a$、$b$ 位置互换),焦点到渐近线的距离恒为 $b$。离心率 $e=\\frac{c}{a}=\\sqrt{1+\\frac{b^{2}}{a^{2}}}>1$,且 $\\frac{b}{a}=\\sqrt{e^{2}-1}$,故渐近线斜率与离心率互相决定;等轴双曲线 $a=b$,渐近线 $y=\\pm x$,离心率 $e=\\sqrt{2}$。焦点三角形面积 $S=b^{2}\\cot\\frac{\\theta}{2}$($\\theta=\\angle F_{1}PF_{2}$);双曲线上点到焦点的距离不小于 $c-a$。\n**方法/思路**\n与椭圆类比而符号相反:方程一加一减,几何关系是 $c^{2}=a^{2}+b^{2}$。用定义解题先判点在左支还是右支,再写 $|PF_{1}|-|PF_{2}|=\\pm2a$。求渐近线:令标准式右边的 1 改 0;与某双曲线共渐近线时设 $\\frac{x^{2}}{a^{2}}-\\frac{y^{2}}{b^{2}}=\\lambda$($\\lambda\\neq0$),$\\lambda>0$ 实轴在 $x$ 轴,$\\lambda<0$ 实轴在 $y$ 轴。求离心率:借渐近线斜率、焦点三角形建立关于 $a$、$c$ 的齐次式,再用 $b^{2}=c^{2}-a^{2}$ 消去 $b$。\n**常考题型与考法**\n①判断方程表示的曲线及焦点位置:两分母异号即双曲线,正号变量对应的坐标轴为实轴;②用定义求焦半径:常得两解,用“到焦点距离不小于 $c-a$”检验取舍;③渐近线与离心率互求:通过 $e=\\sqrt{1+\\frac{b^{2}}{a^{2}}}$ 建立联系;④离心率范围:由渐近线夹角、与直线的位置关系构造不等式;⑤焦点三角形与焦点弦问题(结合“焦点弦问题”节点);⑥共渐近线的双曲线系求方程;⑦与渐近线平行的直线与双曲线只有一个交点但不相切(联立时先看二次项系数)。\n**易错提示**\n几何关系是 $c^{2}=a^{2}+b^{2}$ 且 $c$ 最大,与椭圆相反;离心率 $e>1$,不会小于 1;写 $|PF_{1}|-|PF_{2}|=\\pm2a$ 时勿丢两支的区分,焦半径还要按支分别表达;等轴双曲线 $e=\\sqrt{2}$ 是特殊结论;由渐近线方程反设曲线时勿丢 $\\lambda\\neq0$;求 $b$、$c$ 时注意 $\\sqrt{e^{2}-1}=\\frac{b}{a}$ 中 $b>0$。",
