      "content": "**定义/概念**\n抛物线:平面内到一个定点 $F$(焦点)与一条不经过 $F$ 的定直线 $l$(准线)距离相等的点的轨迹,即 $|MF|=d$($d$ 为 $M$ 到准线的距离),离心率 $e=1$。它是圆锥曲线中唯一开口、不封闭的曲线;定义是解题核心,“到焦点距离”与“到准线距离”可以互相转化,折线最值、焦半径、焦点弦都由此导出。\n**核心公式**\n顶点在原点、对称轴为坐标轴的四种标准形:$y^{2}=2px$($p>0$)开口向右,焦点 $\\left(\\frac{p}{2},0\\right)$,准线 $x=-\\frac{p}{2}$;$y^{2}=-2px$ 开口向左,焦点 $\\left(-\\frac{p}{2},0\\right)$,准线 $x=\\frac{p}{2}$;$x^{2}=2py$ 开口向上,焦点 $\\left(0,\\frac{p}{2}\\right)$,准线 $y=-\\frac{p}{2}$;$x^{2}=-2py$ 开口向下,焦点 $\\left(0,-\\frac{p}{2}\\right)$,准线 $y=\\frac{p}{2}$。$p$ 是焦点到准线的距离,恒正。焦半径:$y^{2}=2px$ 上点 $P(x_{0},y_{0})$ 满足 $|PF|=x_{0}+\\frac{p}{2}$;$x^{2}=2py$ 上点满足 $|PF|=y_{0}+\\frac{p}{2}$。\n**方法/思路**\n求标准方程:先判开口方向与顶点位置确定形式,再代条件求 $p$;形如 $y=ax^{2}$ 先化为 $x^{2}=\\frac{1}{a}y$,则 $p=\\frac{1}{2|a|}$。看开口:方程含 $x$ 的一次项则对称轴为 $x$ 轴,一次项系数的正负定开口左右;含 $y$ 的一次项则对称轴为 $y$ 轴。折线最值:把 $|PF|$ 换成到准线的距离,例如求 $|PA|+|PF|$ 的最小值即点 $A$ 到准线的垂距(结合图形与约束验证)。\n**常考题型与考法**\n①轨迹判定:把“到定点与到定直线的距离差或和”化为相等关系,且定点不在定直线上,即得抛物线;②由方程求焦点、准线:先标准化再读 $p$ 与开口方向;③焦半径与折线最值:定义转化后求最小距离;④焦点弦小题:$x_{1}x_{2}=\\frac{p^{2}}{4}$、$y_{1}y_{2}=-p^{2}$、$|AB|=x_{1}+x_{2}+p$(见“焦点弦问题”节点);⑤过焦点的弦与准线围成图形的性质;⑥以 $y=ax^{2}$ 形式给出时求 $p$、焦点、准线;⑦把“到焦点距离”按定义转为“到准线距离”列方程,结合两点间距离公式解点的坐标与参数。\n**易错提示**\n必须先化成标准形再读 $p$,开口方向决定焦点、准线坐标的符号;焦点坐标是 $\\pm\\frac{p}{2}$ 而不是 $\\pm p$;定义要求焦点不在准线上;由 $y=ax^{2}$ 求 $p$ 时 $p=\\frac{1}{2|a|}$,勿丢绝对值;焦半径公式要按开口方向选用对应坐标;设过焦点的直线用 $x=my+\\frac{p}{2}$,避免漏斜率不存在的通径情形;焦半径向准线距离转化时注意点相对准线的位置与正负。",
