      "content": "**定义/概念**\n“直线与圆锥曲线”研究直线与椭圆、双曲线、抛物线的位置关系,通法为“联立消元 + 判别式 + 韦达定理”:相离、相切、相交对应公共点 0、1、2 个。与直线和圆不同,双曲线、抛物线存在“只有一个交点却不是相切”的情形(与渐近线或对称轴平行),必须先看消元后是否退化为一次方程。\n**核心公式**\n直线 $y=kx+m$ 代入曲线,消元得关于 $x$ 的一元二次方程,记为 $Ax^{2}+Bx+C=0$:若 $A=0$(退化为一次方程),则直线与双曲线渐近线平行或与抛物线对称轴平行,只有一个交点,不算相切;若 $A\\neq0$,则 $\\Delta>0$、$\\Delta=0$、$\\Delta<0$ 分别对应相交、相切、相离。设交点 $A(x_{1},y_{1})$、$B(x_{2},y_{2})$,则 $x_{1}+x_{2}=-\\frac{B}{A}$、$x_{1}x_{2}=\\frac{C}{A}$,弦长 $|AB|=\\sqrt{1+k^{2}}\\cdot|x_{1}-x_{2}|=\\sqrt{1+k^{2}}\\cdot\\frac{\\sqrt{\\Delta}}{|A|}$;当 $k\\neq0$ 时也可用 $|AB|=\\sqrt{1+\\frac{1}{k^{2}}}\\cdot|y_{1}-y_{2}|$。中点弦(点差法):设弦中点 $(x_{0},y_{0})$、弦斜率为 $k$,则椭圆 $k\\cdot\\frac{y_{0}}{x_{0}}=-\\frac{b^{2}}{a^{2}}$(即 $k=-\\frac{b^{2}x_{0}}{a^{2}y_{0}}$),双曲线 $k\\cdot\\frac{y_{0}}{x_{0}}=\\frac{b^{2}}{a^{2}}$,抛物线 $y^{2}=2px$ 中 $k=\\frac{p}{y_{0}}$($x_{0}$、$y_{0}$ 非零时适用,中点为原点的直径情形除外)。\n**方法/思路**\n流程:设直线(优先 $x=my+n$,规避斜率不存在)→联立→由 $\\Delta$ 界定参数范围→写韦达定理→把弦长、中点、面积、斜率积等目标用 $x_{1}+x_{2}$、$x_{1}x_{2}$ 整体表示。点差法分步:设 $A(x_{1},y_{1})$、$B(x_{2},y_{2})$ 均在曲线上,两式相减并因式分解,用 $x_{1}+x_{2}=2x_{0}$、$y_{1}+y_{2}=2y_{0}$ 与 $k=\\frac{y_{1}-y_{2}}{x_{1}-x_{2}}$ 建立关系,最后代回检验 $\\Delta>0$。“设而不求”贯穿始终,不逐一解交点。\n**常考题型与考法**\n①位置判定与参数范围:过椭圆内一点的直线必与椭圆相交,但对双曲线、抛物线不成立;②弦长计算大题:联立→韦达→$|AB|=\\sqrt{1+k^{2}}\\cdot\\frac{\\sqrt{\\Delta}}{|A|}$,并写 $\\Delta>0$ 的范围;③已知弦中点求弦:点差法求 $k$ 后必须代回验证 $\\Delta>0$;④面积问题:$S=\\frac{1}{2}|AB|\\cdot d$($d$ 为点到直线距离);⑤最值、范围在 $\\Delta>0$ 与曲线有界性的共同约束下进行;⑥与抛物线 $y^{2}=2px$ 联立常消 $x$ 得关于 $y$ 的二次方程,便于使用纵坐标关系。\n**易错提示**\n圆锥曲线联立后二次项系数可能为 0,须先讨论再谈判别式;判别式针对消元后的方程,其系数 $A$ 勿与椭圆长半轴 $a$ 混淆;点差法结论要验证弦存在($\\Delta>0$)且斜率存在;直线过椭圆内部一点必有两交点,但对双曲线、抛物线不一定;弦长公式中的 $\\Delta$ 是消元后二次方程的判别式;斜截式不能表示竖直线,需换 $x=my+n$ 或单独讨论。",
