      "content": "**定义/概念** 数列是按确定顺序排列的一列数；第 $n$ 项记作 $a_{n}$，首项为 $a_{1}$，$\\{a_{n}\\}$ 表示整个数列。它是定义域为正整数集（或其有限子集 $\\{1,2,\\cdots,n\\}$）的特殊函数，图象是一群孤立点。按项数分有穷、无穷数列；按增减趋势分递增、递减、常数列、摆动数列。\n**核心公式/性质** 通项公式 $a_{n}=f(n)$；递推公式（如 $a_{n+1}=2a_{n}+1$）给出相邻（或前几）项的关系，须连同首项才能确定数列。前 $n$ 项和：\n$$S_{n}=a_{1}+a_{2}+\\cdots+a_{n}$$\n$$a_{1}=S_{1}\\ (n=1);\\qquad a_{n}=S_{n}-S_{n-1}\\ (n\\geq2)$$\n用 $S_{n}$ 求出的通式须回验 $n=1$ 是否能并入。\n**方法/思路** 由前几项归纳通项：先定符号因子（$(-1)^{n}$ 或 $(-1)^{n+1}$），再看绝对值部分的等差、等比或 $2^{n}-1$ 结构。判断某数是否为数列的项：令 $a_{n}=N$ 解 $n$，得正整数即是。判断单调性：比较 $a_{n+1}-a_{n}$ 与 0（正项数列也可比较 $\\frac{a_{n+1}}{a_{n}}$ 与 1）。\n**常考题型与考法** ①归纳通项选填：给出 $-1,3,-7,15,\\cdots$（或 $-\\frac{3}{2},\\frac{4}{7},-\\frac{5}{14},\\cdots$ 类）选可行的通项公式——用 $n=1,2$ 代入选项排除，再核对符号与分母结构，注意“通项不唯一、只需选可行”。②判断项的序号：已知通项与某数，解方程 $a_{n}=N$，解得正整数 $n$ 即是该项，解出分数或负数则不是。③由递推求项：给出 $a_{n+1}$ 与 $a_{n}$ 的关系及 $a_{1}$，逐项代入求 $a_{2},a_{3}$；分段递推（按奇偶给不同式子）要分 $n$ 的奇偶分别代入。④由 $S_{n}$ 求通项：$S_{n}=n^{2}+1$ 型，先算 $a_{1}=S_{1}=2$，再对 $n\\geq2$ 作差得 $a_{n}=2n-1$，因 $n=1$ 时 $2n-1=1\\neq2$，须分段书写——这是“合并/分段”的经典设坑。⑤最大（小）项：解 $a_{n}\\geq a_{n+1}$ 且 $a_{n}\\geq a_{n-1}$ 的双向不等式，或转化为函数最值。\n**易错提示** ①由前几项猜出的通项不唯一，判断“是否为数列的项”须解方程而非目测。②$a_{n}=S_{n}-S_{n-1}$ 只对 $n\\geq2$ 成立，$n=1$ 须单独验证。③下标从 $a_{1}$ 开始，不存在 $a_{0}$。④分段递推别把奇偶条件代反。",
