      "keywords": [
        "等差数列",
        "公差",
        "通项",
        "前n项和",
        "等差中项"
      ],
      "content": "**定义/概念** 等差数列：从第 2 项起，$a_{n+1}-a_{n}=d$（常数 $d$ 为公差）；等价条件是等差中项 $2a_{n}=a_{n-1}+a_{n+1}$（$n\\geq2$）。$d>0$ 递增，$d<0$ 递减，$d=0$ 为常数列。\n**核心公式/性质**\n$$a_{n}=a_{1}+(n-1)d=a_{m}+(n-m)d$$\n$$S_{n}=\\frac{n(a_{1}+a_{n})}{2}=na_{1}+\\frac{n(n-1)}{2}d$$\n性质：$m+n=p+q$ 时 $a_{m}+a_{n}=a_{p}+a_{q}$；$\\{\\frac{S_{n}}{n}\\}$ 成等差数列（公差 $\\frac{d}{2}$）；$S_{m},\\ S_{2m}-S_{m},\\ S_{3m}-S_{2m}$ 成等差数列（公差 $m^{2}d$）；$S_{n}$ 是 $n$ 的二次函数且无常数项。\n**方法/思路** 设基本量 $a_{1}$、$d$，用两个独立条件列方程组；优先用下标和性质避免逐项计算；求 $S_{n}$ 的最值找“变号项”：解 $a_{n}\\geq0$ 且 $a_{n+1}\\leq0$ 确定使和最大的 $n$（或把 $S_{n}$ 配方后用二次函数取整）。\n**常考题型与考法** ①基本量运算：给 $a_{2}$、$a_{5}$ 或某几项的和求通项与前 $n$ 项和——列 $a_{1}+d$、$a_{1}+4d$ 的方程解 $a_{1}$、$d$；已知 $S_{n}=2n^{2}-3n$ 型用作差得 $a_{n}=4n-5$（$n\\geq2$）并验证 $n=1$ 后合并为一段式。②下标和性质速算：$a_{1}+a_{7}=a_{2}+a_{6}=2a_{4}$，已知 $a_{4}$ 求 $S_{7}=7a_{4}$；或给 $a_{1}+a_{n}$ 为定值直接用 $S_{n}=\\frac{n(a_{1}+a_{n})}{2}$。③片段和：已知 $S_{m}$、$S_{2m}$ 求 $S_{3m}$——由 $S_{m},S_{2m}-S_{m},S_{3m}-S_{2m}$ 成等差列方程，是选择压轴的常见考法。④$S_{n}$ 最值与变号项：判断“前 $n$ 项和最大时 $n=?$”，解 $a_{n}\\geq0$、$a_{n+1}\\leq0$；若对称轴非整数，须比较相邻整数的 $S_{n}$。⑤综合证明：由 $S_{n}=An^{2}+Bn$ 型反推等差数列，或直接用等差中项 $2a_{n}=a_{n-1}+a_{n+1}$ 证明。\n**易错提示** ①$S_{n}=An^{2}+Bn+C$ 且 $C\\neq0$ 时只有 $n\\geq2$ 起成等差，首项 $a_{1}=S_{1}$ 须单独算。②下标和性质要求 $m+n=p+q$ 成立才能用。③$S_{2m}-S_{m}$ 是“后 $m$ 项之和”，勿写成 $S_{2m-m}$。④含参等差数列先讨论公差符号，再谈单调与最值。",
