      "keywords": [
        "等比数列",
        "公比",
        "通项",
        "前n项和",
        "等比中项"
      ],
      "content": "**定义/概念** 等比数列：从第 2 项起，$\\frac{a_{n+1}}{a_{n}}=q$（非零常数 $q$ 为公比）；等价条件是等比中项 $a_{n}^{2}=a_{n-1}a_{n+1}$（$n\\geq2$）。$a_{1}$、$q$ 及各项均非零；$q>0$ 各项同号，$q<0$ 正负摆动，$|q|<1$ 时 $|a_{n}|$ 趋于 0。\n**核心公式/性质**\n$$a_{n}=a_{1}q^{n-1}=a_{m}q^{n-m}$$\n$q=1$ 时：$S_{n}=na_{1}$\n$q\\neq1$ 时：\n$$S_{n}=\\frac{a_{1}(1-q^{n})}{1-q}=\\frac{a_{1}-a_{n}q}{1-q}$$\n性质：$m+n=p+q$ 时 $a_{m}a_{n}=a_{p}a_{q}$；$S_{m},S_{2m}-S_{m},S_{3m}-S_{2m}$ 成等比数列（公比 $q^{m}$，$q\\neq-1$ 时成立）；结构特征 $S_{n}=kq^{n}-k$（$k\\neq0$，$q\\neq1$）$\\Leftrightarrow\\{a_{n}\\}$ 为等比数列。\n**方法/思路** 设 $a_{1}$、$q$ 两个基本量列方程；两式相除整体消去 $a_{1}$ 求 $q$（避免逐项展开）；凡用前 $n$ 项和公式先问“$q=1$ 是否可能”再分类；构造型递推 $a_{n+1}=pa_{n}+q$ 先配常数构造等比（见递推节点）。\n**常考题型与考法** ①基本量求值：知 $a_{3}=2$、$a_{6}=16$，两式相除得 $q^{3}=8$ 即 $q=2$，再代回求 $a_{1}$ 与通项；$q$ 有正负两解（如 $q^{2}=a$ 形式）时须结合题设（各项符号、递增递减）取舍。②由 $S_{n}$ 与 $a_{n}$ 混合关系证等比：$S_{n}=2a_{n}-1$ 型，先 $a_{1}=S_{1}$，再对 $n\\geq2$ 作差得 $a_{n}=2a_{n-1}$，由定义说明 $\\{a_{n}\\}$ 是等比数列——解答题第(1)问的标准流程，注意“$n\\geq2$ 起验证”。③前 $n$ 项和计算：$q\\neq1$ 直接代公式；含“公比是否等于 1”的参数题须讨论；已知 $S_{m}$、$S_{2m}$ 求 $S_{3m}$ 用片段和等比性质或先求 $q^{m}$。④实际情境建模：增长率、面积逐年变化类问题给出 $a_{n+1}$ 与 $a_{n}$ 的一次关系，先构造等比求通项，再求前 $n$ 项和回答“几年后达到某值”。\n**易错提示** ①漏掉 $q=1$ 的单独讨论是等比板块头号错误。②由 $a_{n}^{2}$ 推等比中项时符号要结合各项同号性判断（两个同号数才有等比中项）。③片段和成等比性质在 $q=-1$ 时会出现零项而失效，用前先说明条件。④$a_{n}=a_{1}q^{n-1}$ 中指数是 $n-1$，求和公式里不要错写成 $q^{n}$。",
