      "content": "**定义**:命题是可判断真假的陈述句;常用逻辑用语研究四种命题的真假关系与全称、特称命题的否定。\n**核心公式与性质**:原命题\"若 $p$ 则 $q$\"与逆否命题\"若 $\\neg q$ 则 $\\neg p$\"同真假(互为逆否等价);逆命题与否命题也互为逆否、同真假。命题的否定:$$\\neg(\\forall x\\in M,\\ p(x))\\ \\Leftrightarrow\\ \\exists x\\in M,\\ \\neg p(x)$$ $$\\neg(\\exists x\\in M,\\ p(x))\\ \\Leftrightarrow\\ \\forall x\\in M,\\ \\neg p(x)$$ 即量词互换、结论否定。联结词否定:$\\neg(p\\wedge q)\\Leftrightarrow\\neg p\\vee\\neg q$、$\\neg(p\\vee q)\\Leftrightarrow\\neg p\\wedge\\neg q$。复合命题真值:$p\\wedge q$ 一假即假,$p\\vee q$ 一真即真。\n**方法/思路**:①写否定:先判量词类型→换量词→否结论(结论中的且/或互换);②判真假:全称命题证伪举反例,特称命题求真举实例;③四种命题:原命题难证时改证逆否命题。\n**常考题型与考法**:①\"命题的否定\"必考选填:如 $\\neg(\\forall x>0,\\ x^{2}+x>0)$ 应为 $\\exists x>0,\\ x^{2}+x\\leq 0$,陷阱常设在量词漏换或不等号方向;②全称/特称命题真假与求参:如\"$\\exists x\\in R,\\ ax^{2}+2x+1=0$ 为真\"⇔ $a=0$ 或 $\\Delta\\geq 0$,即方程有解问题;\"$\\forall x$ 不等式成立\"为真则化为恒成立;③复合命题真假求参:$p\\wedge q$ 为真取两参数集之交,$p\\vee q$ 为真取并;④四种命题真假关系的概念题,牢记\"互为逆否才等价\"。\n**易错提示**:\"否命题\"(条件结论都否定)与\"命题的否定\"(只否结论)不同;否定含量词命题时量词与结论必须同时改;\"$p$ 或 $q$\"的否定是\"$\\neg p$ 且 $\\neg q$\",且或互换勿漏。",
      "links": [
        "set-cond",
        "set-op",
        "ineq-const"
      ],
      "book": "必修一",
