      "content": "**定义**\n两个非零向量 $a$、$b$ 共起点后的夹角 $\\theta\\in[0,\\pi]$,数量积\n$$a\\cdot b=|a||b|\\cos\\theta$$\n结果是数量不是向量;规定零向量与任何向量的数量积为0。物理背景:功 $W=F\\cdot s$。\n**核心定理与公式**\n几何意义:$b$ 在 $a$ 方向上的数量投影为 $|b|\\cos\\theta$;$a$ 在 $b$ 方向上的投影向量是 $\\frac{a\\cdot b}{|b|^{2}}b$。性质:$a\\perp b$⇔ $a\\cdot b=0$(非零向量);$a\\cdot a=|a|^{2}$,故 $|a|=\\sqrt{a\\cdot a}$(求模先平方);$\\cos\\theta=\\frac{a\\cdot b}{|a||b|}$;$|a\\cdot b|\\le|a||b|$;同向时 $a\\cdot b=|a||b|$,反向时为 $-|a||b|$。运算律:交换律、数乘结合律、分配律。注意:数量积不满足结合律与消去律,由 $a\\cdot b=a\\cdot c$ 推不出 $b=c$。\n**方法/思路**\n求数量积的三条路:定义式(知模与夹角)、基底法(把向量用已知夹角模长的基底表示)、坐标法;求模长先平方再用 $a\\cdot a=|a|^{2}$;证明垂直只须证 $a\\cdot b=0$;展开 $(a\\pm b)^{2}=|a|^{2}+|b|^{2}\\pm 2a\\cdot b$ 是求模与夹角的常用桥梁。夹角公式要求两向量共起点,不共起点先平移;由 $a\\cdot b$ 的正负可直接判断夹角是锐角、直角还是钝角,几何意义明确。\n**常考题型与考法**\n①求投影向量(6.3题型1):区分投影的数量与投影向量,投影向量按 $\\frac{a\\cdot b}{|b|^{2}}b$ 算。②数量积计算(6.3题型2):给模与夹角直接算,或拆基底算。③求夹角(6.3题型3):用 $\\cos\\theta=\\frac{a\\cdot b}{|a||b|}$ 或坐标公式。④已知夹角或垂直求参数(6.3题型4):由余弦定值或 $a\\cdot b=0$ 列方程。⑤求模与已知模求参数(6.3题型5、6):平方展开 $|a\\pm b|^{2}$。⑥数量积与最值:已知 $|a|$、$|b|$ 及夹角范围(或给坐标),把目标数量积写成变量函数求范围,常用配方法、二次函数或基本不等式。⑦数量积与图形:在 $\\triangle ABC$ 中 $\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=|AB||AC|\\cos A$,可求角、数量积或判锐角直角;矩形邻边点积为 0,菱形对角线互相垂直,正方形用模相等加点积为 0 刻画。\n**易错提示**\n$a\\cdot b=0$ 还可能是 $a=0$ 或 $b=0$,不能直接断言垂直;夹角钝角⇔ $a\\cdot b<0$,但 $a\\cdot b>0$ 还包含同向共线情形,判“锐角”要剔除共线同向;展开 $(a+b)^{2}$ 勿漏 $2a\\cdot b$ 项;投影向量与投影(数量)别混;数量积无消去律,等式两边不能约去 $a$;若 $a$、$b$ 中有零向量,夹角无定义,数量积按 0 处理。",
