      "content": "**定义**\n把向量放入坐标系后用坐标计算数量积及相关量,使垂直、平行、夹角、距离全部代数化。\n**核心定理与公式**\n设 $a=(x_{1},y_{1})$、$b=(x_{2},y_{2})$:\n$$a\\cdot b=x_{1}x_{2}+y_{1}y_{2},\\qquad |a|=\\sqrt{x_{1}^{2}+y_{1}^{2}}$$\n两点间距离:$|\\overrightarrow{AB}|=\\sqrt{(x_{2}-x_{1})^{2}+(y_{2}-y_{1})^{2}}$。夹角余弦:\n$$\\cos\\theta=\\frac{a\\cdot b}{|a||b|}=\\frac{x_{1}x_{2}+y_{1}y_{2}}{\\sqrt{x_{1}^{2}+y_{1}^{2}}\\sqrt{x_{2}^{2}+y_{2}^{2}}}$$\n垂直条件:$a\\perp b$⇔ $x_{1}x_{2}+y_{1}y_{2}=0$。共线条件:$a\\parallel b$($b\\ne 0$)⇔ $x_{1}y_{2}-x_{2}y_{1}=0$。数量投影:$a$ 在 $b$ 方向上的投影 $=\\frac{a\\cdot b}{|b|}=\\frac{x_{1}x_{2}+y_{1}y_{2}}{\\sqrt{x_{2}^{2}+y_{2}^{2}}}$。与 $a$ 同向的单位向量是 $\\frac{a}{|a|}$。\n**方法/思路**\n坐标化通法:先求各点坐标→把所求向量写成坐标(终点减起点)→套公式。求夹角、判断垂直平行、求模、求投影都直接代坐标;垂直给出方程、共线给出比例关系,联立可解参数或最值。判断图形形状:两邻边向量点积为 0 得直角,模相等再结合点积可判菱形、正方形;求对角线夹角、中线长直接坐标化。求最值时先明确变量与约束(垂直、共线、模长等式给出约束),把目标写成坐标的函数再配方或放缩。\n**常考题型与考法**\n①线性与数量积的坐标运算(6.4题型4、5):按分量直接算。②共线、垂直的坐标表示(6.4题型6):列方程求参数,或判断三角形形状、四边形性质。③坐标运算的几何应用(6.4题型7、6.10题型6):坐标法证平行垂直、求角与长度。④夹角公式与最值(6.10题型4):求夹角余弦的范围、数量积最值,常转化为二次函数或基本不等式。⑤投影与最值:数量投影 $\\frac{a\\cdot b}{|b|}=\\frac{x_{1}x_{2}+y_{1}y_{2}}{|b|}$ 也是坐标函数,可与二次函数、基本不等式结合求范围。⑥含参向量问题:向量带参数时,垂直给出方程 $x_{1}x_{2}+y_{1}y_{2}=0$、共线给出 $x_{1}y_{2}-x_{2}y_{1}=0$,解出参数后再求模、夹角或数量积范围。\n**易错提示**\n平行与垂直条件互换是常见错误:平行看 $x_{1}y_{2}-x_{2}y_{1}=0$,垂直看 $x_{1}x_{2}+y_{1}y_{2}=0$;余弦可负(钝角),题目要求“夹角为锐角”时还要排除同向共线,由 $a\\cdot b>0$ 判锐角时必须两向量不共线同向;分母模不能为0,含字母的坐标要先讨论模是否为 0;向量的起点不在原点时坐标要“终点减起点”,即先写 $\\overrightarrow{AB}=\\overrightarrow{OB}-\\overrightarrow{OA}$ 再取坐标。",
