      "content": "**定义**\n向量是数形结合的工具,用向量证明平面几何问题就是把几何关系翻译成向量等式,通过运算得出结论再翻译回去。\n**核心定理与公式**\n三步曲:转化(用向量表示几何元素)→运算(基底或坐标运算研究平行、垂直、长度、夹角)→翻译(还原为几何结论)。常用工具:平行共线——$a\\parallel b$⇔ 存在 $\\lambda$ 使 $b=\\lambda a$;垂直——$a\\cdot b=0$;长度——$|\\overrightarrow{AB}|=\\sqrt{a\\cdot a}$;夹角——$\\cos\\theta=\\frac{a\\cdot b}{|a||b|}$。典型结论:四边形 $ABCD$ 为平行四边形⇔ $\\overrightarrow{AB}=\\overrightarrow{DC}$(或对角线互相平分);$G$ 为重心⇔ $\\overrightarrow{GA}+\\overrightarrow{GB}+\\overrightarrow{GC}=0$;以 $AB$ 为直径的圆上任一点 $P$ 满足 $\\overrightarrow{PA}\\cdot\\overrightarrow{PB}=0$;极化恒等式:\n$$a\\cdot b=\\frac{|a+b|^{2}-|a-b|^{2}}{4}$$\n**方法/思路**\n选基底优先取模长、夹角已知的向量($\\overrightarrow{AB}$、$\\overrightarrow{AC}$);直接建系用坐标运算更机械;用向量推导几何恒等式是通法:把边长写成向量,平方取模再展开,即得余弦定理、中线长公式、平行四边形对角线与边长的关系等;注意“翻译”环节:向量共线要排除零向量,数量积为0对应垂直要两向量非零。\n**常考题型与考法**\n①证平行、垂直、夹角、长度四大类(6.5题型1~4):如证 $MN\\parallel BC$、证四边形为矩形、求角度与线段长。②向量与几何最值(6.5题型5、6.10题型8):设动点参数化,把数量积、模写成功率,用函数或基本不等式求最值;极化恒等式把数量积化到中线长。③其他几何应用(6.5题型6)与物理应用(6.5题型7):力的合成用平行四边形法则,功 $W=F\\cdot s$。④综合大题(6.7):坐标化解四边形、三角形综合问题。⑤向量与圆:以 $AB$ 为直径的圆上点 $P$ 满足 $\\overrightarrow{PA}\\cdot\\overrightarrow{PB}=0$,可用点积为 0 证点在圆上、求轨迹。⑥向量与三角形四心、面积比(见“向量与三角形的四心”节点):重心条件 $\\overrightarrow{GA}+\\overrightarrow{GB}+\\overrightarrow{GC}=0$、奔驰定理等,是几何向量综合题常考结论。\n**易错提示**\n证垂直须先确认两向量非零;由向量共线得线线平行时要排除零向量退化;长度结果是模,开方前先平方;极化恒等式使用前提是找到公共起点;物理题注意力与位移的夹角是共起点夹角,功有正负。",
