      "content": "**定义/概念**\n只含一个未知数、最高次数为 $2$ 的不等式 $ax^{2}+bx+c>0$($<0$、$\\ge 0$、$\\le 0$,$a\\ne 0$)叫一元二次不等式。它与二次函数 $y=ax^{2}+bx+c$、一元二次方程 $ax^{2}+bx+c=0$ 合称“三个二次”:方程根是抛物线与 $x$ 轴交点的横坐标,也是不等式解集的分界点;解不等式即确定使函数值为正(负)的自变量范围。求函数定义域、集合交并运算、含参命题真假的判断,常归结为解一元二次不等式。\n**核心公式**\n设 $\\Delta=b^{2}-4ac$。当 $a>0$ 时:若 $\\Delta>0$ 且两根 $x_{1}<x_{2}$,则 $ax^{2}+bx+c>0$ 的解集为 $x<x_{1}$ 或 $x>x_{2}$(大于取两边),$ax^{2}+bx+c<0$ 的解集为 $x_{1}<x<x_{2}$(小于取中间);若 $\\Delta=0$,则 $ax^{2}+bx+c>0$ 的解集为 $x\\ne x_{0}$,$ax^{2}+bx+c<0$ 无解;若 $\\Delta<0$,则 $ax^{2}+bx+c>0$ 的解集为 $\\mathbf{R}$,$ax^{2}+bx+c<0$ 无解。韦达定理:$x_{1}+x_{2}=-\\frac{b}{a}$、$x_{1}x_{2}=\\frac{c}{a}$,是“由解集求参数”的主要工具。\n**方法/思路**\n解不含参型三步:移项使右边为 $0$ 并把 $a$ 化为正($a<0$ 先乘 $-1$ 变号)→求 $\\Delta$ 与根→按口诀写解集。例:$-x^{2}+3x+4>0$ 先化 $x^{2}-3x-4<0$,即 $(x-4)(x+1)<0$,解集为 $-1<x<4$。高次整式用数轴标根(穿根)法:化 $a>0$、分解因式、根标数轴,从右上方穿起,奇次根穿过、偶次根弹回。含参讨论依次三件事:二次项系数是否为 $0$ 及正负(决定是否退化为一次、开口方向)、$\\Delta$ 符号(根的个数)、两根大小(解集次序),逐层分类合并,如解 $a(x-1)(x-a)>0$ 须按 $a$ 与 $0$、$1$ 与 $a$ 的关系分段。\n**常考题型与考法**\n①解不含参不等式(小题):口诀或穿根直接写区间。②含参分类讨论:先固定二次项系数符号,再比较参数根与常数根的大小。③已知解集反求参数:解集端点即两根,用韦达定理或代入端点,并用解集形状核对 $a$ 的符号(解集取“两边”说明 $a>0$)。④恒成立/无解(选填):转为 $a$、$\\Delta$ 条件,如 $x^{2}+ax+1>0$ 对 $x\\in\\mathbf{R}$ 恒成立 $\\Leftrightarrow \\Delta=a^{2}-4<0$,即 $-2<a<2$。⑤与集合、充分必要条件结合:先解不等式得解集,再求交集并集或判断推出关系。\n**易错提示**\n$a=0$ 退化为一次不等式要单独讨论;忘把 $a$ 化正导致“大于取两边”用反;$\\Delta=0$ 与 $\\Delta<0$ 时“无解”“恒成立”结论易混;分式不等式先移项通分,勿直接去分母;写解集时注意端点开闭,分母、根号内为 $0$ 的点要剔除。",
