      "content": "**定义/概念**\n含参恒成立:对给定区间内所有 $x$,含参数的不等式都成立,求参数取值范围;能成立(有解、存在性):至少存在一个 $x$ 使不等式成立。二者仅一字之差,转化方向相反,极易混淆,是函数、不等式、导数综合题的高频考点,常在解答题第一问出现。\n**核心公式**\n恒成立:若 $f(x)\\ge a$ 对 $x\\in D$ 恒成立,则 $a$ 不大于 $f(x)$ 在 $D$ 上的最小值;若 $f(x)\\le a$ 恒成立,则 $a$ 不小于 $f(x)$ 在 $D$ 上的最大值。能成立:存在 $x\\in D$ 使 $f(x)\\ge a$,等价于 $a$ 不大于 $f(x)$ 的最大值;存在 $x\\in D$ 使 $f(x)\\le a$,等价于 $a$ 不小于 $f(x)$ 的最小值。二次型在 $\\mathbf{R}$ 上:$ax^{2}+bx+c>0$ 恒成立 $\\Leftrightarrow a>0$ 且 $\\Delta<0$;$ax^{2}+bx+c\\ge 0$ 恒成立 $\\Leftrightarrow a>0$ 且 $\\Delta\\le 0$;若 $a$ 可为 $0$,须先检验 $a=0$ 是否满足。\n**方法/思路**\n①分离参数:能分离时化为 $a>g(x)$ 或 $a<g(x)$ 恒成立,求 $g(x)$ 的最值;求最值可用基本不等式、对勾函数、导数;除以含参因式时必须讨论其符号。②直接分类讨论:二次函数在闭区间恒正(负),按对称轴与区间端点的位置分类,比较端点与顶点函数值。③变换主元:已知参数范围而变量可变时,把参数当自变量,原式化为关于参数的一次函数,由端点函数值控制。④数形结合与换元:图像恒在直线一侧;令 $t=g(x)$ 时同步确定新元范围。例:$x\\in[1,3]$ 时 $x^{2}-ax+4\\ge 0$ 恒成立,分离得 $a\\le x+\\frac{4}{x}$ 恒成立,右边最小值为 $4$($x=2$ 取),故 $a\\le 4$。\n**常考题型与考法**\n①$\\mathbf{R}$ 上恒成立(选填):直接用 $a$、$\\Delta$ 条件,勿漏 $a=0$。②区间恒成立(大题第一问常考):优先分离参数求最值;分母含 $x$ 时讨论符号或移项分类。③能成立(有解):把“任意”换成“存在”后最值方向取反,如 $x^{2}+ax+1<0$ 有解 $\\Leftrightarrow \\Delta=a^{2}-4>0$。④二次不等式在某区间有解:转化为该区间内最大值(最小值)与 $0$ 的关系。⑤与导数结合:$f(x)\\ge g(x)$ 恒成立,构造 $h(x)=f(x)-g(x)$ 求最小值非负,或先证局部不等式再放大。⑥参数在二次项系数中:先讨论 $a=0$ 退化,再按 $\\Delta$ 分类。\n**易错提示**\n“恒成立”与“有解”取最值的方向写反是头号错误;漏掉二次项系数为 $0$ 的退化情形;分离参数后忽略定义域端点取不到,导致取等失效;区间开闭影响答案端点;换元后新元范围必须同步确定;能成立问题常与恒成立问题在同一题干中互换,须逐字读题。",
