      "content": "**定义/概念**\n为让方程 $x^{2}+1=0$ 有解,引入虚数单位 $i$,规定 $i^{2}=-1$($i$ 是 $x^{2}+1=0$ 的一个根),并允许实数与 $i$ 按原有运算律加乘,数系因此由实数扩充到复数:自然数集、整数集、有理数集、实数集依次都是复数集的子集,即 $\\mathbf{N}\\subset\\mathbf{Z}\\subset\\mathbf{Q}\\subset\\mathbf{R}\\subset\\mathbf{C}$。形如 $z=a+bi$($a,b\\in\\mathbf{R}$)的数叫复数,其中 $a$ 叫实部,$b$ 叫虚部(注意虚部是实数 $b$ 而非 $bi$)。复数不能像实数那样比较大小,只有两个复数同为实数时才可比较大小;但复数相等有严格标准,可转化为实数方程组处理。\n**核心公式**\n分类($z=a+bi$,$a,b\\in\\mathbf{R}$):$b=0\\Leftrightarrow z$ 是实数;$b\\ne 0\\Leftrightarrow z$ 是虚数;$a=0$ 且 $b\\ne 0\\Leftrightarrow z$ 是纯虚数。复数相等:$a+bi=c+di$($a,b,c,d\\in\\mathbf{R}$)$\\Leftrightarrow a=c$ 且 $b=d$。模与共轭的基础关系:模 $|z|=\\sqrt{a^{2}+b^{2}}$;共轭 $\\bar{z}=a-bi$,且 $z+\\bar{z}=2a\\in\\mathbf{R}$、$z-\\bar{z}=2bi$、$z\\cdot\\bar{z}=a^{2}+b^{2}=|z|^{2}$。\n**方法/思路**\n解“$z$ 是什么数”类问题,先把含 $i$ 的结构化简成 $a+bi$ 标准形,再按分类条件列式:$z$ 为实数 $\\Leftrightarrow$ 虚部 $b=0$;$z$ 为纯虚数 $\\Leftrightarrow$ 实部 $a=0$ 且虚部 $b\\ne 0$;实部与虚部相等、相反或成比例则分别列等式。例如 $z=(m^{2}-5m+6)+(m^{2}-3m+2)i$ 为纯虚数,须 $m^{2}-5m+6=0$ 且 $m^{2}-3m+2\\ne 0$,解得 $m=3$(舍去使虚部同时为 $0$ 的 $m=2$)。含未知 $z$ 的方程先设 $z=a+bi$,比较实虚部列实数方程组,解出后回代检验附加条件。\n**常考题型与考法**\n①概念辨析选择题:判断“虚部是 $bi$”“实部为零即纯虚数”“$i$ 是 $x^{2}+1=0$ 的根”“实数是复数”等说法的正误。②由“$z$ 为实数/虚数/纯虚数”求参数:列实部虚部条件,纯虚数要排除虚部同为 $0$ 的值。③已知实部虚部关系求参数:如实部等于虚部、虚部是实部的相反数。④复数相等求参数:$x,y\\in\\mathbf{R}$ 且 $(x+y)+(x-y)i=2+4i$,得 $x+y=2$、$x-y=4$,解得 $x=3$、$y=-1$。⑤结合复平面:判断对应点在象限、坐标轴还是虚轴上,为几何意义学习作铺垫。\n**易错提示**\n虚部是 $b$ 不是 $bi$,$2-3i$ 的虚部是 $-3$;纯虚数必须同时满足实部为 $0$ 与虚部不为 $0$,只令实部为 $0$ 会把 $0$ 误判为纯虚数;含 $i$ 的幂、乘除必须先化简再判断类型;虚数之间不能比较大小;解出的参数要回代,检查是否使原式分母为零或不符合附加条件;只有 $a$、$b$ 都是实数时才能称 $a+bi$ 的实部虚部,才可用复数相等列方程。",
