      "content": "**定义/概念**:二项式定理给出 $(a+b)^{n}$ 展开的规律:展开式第 $k+1$ 项的系数恰为组合数 $\\mathrm{C}_{n}^{k}$(称二项式系数);$a$ 按降幂、$b$ 按升幂排列,每项中 $a$、$b$ 的指数和恒为 $n$;展开式共 $n+1$ 项。\n**核心公式**:\n$$(a+b)^{n}=\\sum_{k=0}^{n}\\mathrm{C}_{n}^{k}a^{n-k}b^{k}$$\n通项(第 $k+1$ 项):\n$$T_{k+1}=\\mathrm{C}_{n}^{k}a^{n-k}b^{k},\\quad k=0,1,\\dots,n$$\n特例:$(1+x)^{n}=\\sum_{k=0}^{n}\\mathrm{C}_{n}^{k}x^{k}$;$(a-b)^{n}$ 展开时各项符号正负相间。\n**方法/思路**:写通项时把 $a$、$b$ 对应的“整块”(连同负号、系数、分式)整体代入,如 $(2x-\\frac{1}{x^{2}})^{6}$ 中令 $b=-\\frac{1}{x^{2}}$;化简通项时把常数部分与 $x$ 的指数分开整理、合并指数;牢记“第几项”与 $k$ 相差1——第4项对应 $k=3$;逆用定理可把形如 $\\sum_{k=0}^{n}\\mathrm{C}_{n}^{k}(\\text{含}x)^{k}$ 的式子还原为二项式。\n**常考题型与考法**:①直接展开(怎么考:展开 $(x+2)^{3}$ 或问 $(a+b)^{6}$ 有几项;解法:套定理,项数为 $n+1$);②特定项(怎么考:求第4项或含 $x^{3}$ 的项;解法:通项中令对应指数取要求值);③逆用化简(怎么考:把 $\\mathrm{C}_{4}^{0}2^{4}-\\mathrm{C}_{4}^{1}2^{3}x+\\cdots-\\mathrm{C}_{4}^{4}x^{4}$ 化为 $(2-x)^{4}$;解法:识别展开结构还原);④反求参数(怎么考:常数项为第7项求 $n$;解法:通项令指数为0建方程并检验 $k$);⑤三项式转化(怎么考:$(1+x+x^{2})^{n}$ 中的项;解法:按需两两合并成二项或用展开思想分类)。\n**易错提示**:通项下标易错位——$T_{k+1}$ 对应第 $k+1$ 项;二项式系数 $\\mathrm{C}_{n}^{k}$ 与“某项的系数”不同,后者还含 $a$、$b$ 自带常数与符号的乘积;代入含负号的 $b$ 时要整体带括号,防止符号错乱;化简 $x^{-k}$ 类指数时勿漏负号。",
