      "core": 2,
      "keywords": [
        "杨辉三角",
        "对称性",
        "最大项",
        "系数和",
        "2ⁿ"
      ],
      "content": "**定义/概念**:把 $(a+b)^{n}$ 展开式的二项式系数 $\\mathrm{C}_{n}^{k}$($k=0,1,\\dots,n$)按行排列即得杨辉三角:每行两端为1,其余每个数等于上一行“肩上”两数之和;它直观呈现了二项式系数的对称、递增递减与求和等全部性质。\n**核心公式**:对称性 $\\mathrm{C}_{n}^{k}=\\mathrm{C}_{n}^{n-k}$。增减与最大:系数先增后减,$n$ 为偶数时中间一项 $\\mathrm{C}_{n}^{\\frac{n}{2}}$ 最大;$n$ 为奇数时中间两项 $\\mathrm{C}_{n}^{\\frac{n-1}{2}}$ 与 $\\mathrm{C}_{n}^{\\frac{n+1}{2}}$ 相等且最大。各项二项式系数和\n$$\\sum_{k=0}^{n}\\mathrm{C}_{n}^{k}=2^{n}$$\n奇数项(下标为奇数)系数和 $=$ 偶数项(下标为偶数)系数和 $=2^{n-1}$。\n**方法/思路**:求和问题首选赋值法:对 $(1+x)^{n}$ 的展开式令 $x=1$ 得 $2^{n}$;对一般展开式 $\\sum_{i}a_{i}x^{i}$,令 $x=1$ 得各项系数和,令 $x=-1$ 得正负交替和,两式相加除以2得偶次项系数和、相减除以2得奇次项系数和。求展开式中“系数”(含符号与常数)最大项时不能只看二项式系数,须比较相邻两项系数(作比值判断 $k$ 的范围)。\n**常考题型与考法**:①二项式系数最大项(怎么考:$(a+b)^{n}$ 展开式中系数最大的项;解法:按 $n$ 奇偶定中间位置,注意项号=下标+1);②各项系数和(怎么考:对 $(2x-1)^{n}$ 求展开式各项系数和;解法:令 $x=1$ 得 $(2-1)^{n}=1$,与二项式系数和 $2^{n}$ 区分);③奇偶项系数和(怎么考:求奇数项系数和;解法:赋值 $x=1$ 与 $x=-1$ 相加减);④杨辉三角规律(怎么考:由三角写某行数字或证相邻数字成比例;解法:利用递推式 $\\mathrm{C}_{n+1}^{k}=\\mathrm{C}_{n}^{k}+\\mathrm{C}_{n}^{k-1}$);⑤整除与近似(怎么考:证与 $(1+x)^{n}$ 展开相关的整除或求近似值;解法:把底数拆成“1+小量”展开取有限项)。\n**易错提示**:勿混“二项式系数和”($2^{n}$)与“各项系数和”(令变量等于1);$n$ 为奇数时最大项有两个;含负号、系数的展开式中“系数最大项”未必在中间,必须逐对比较;赋值 $x=-1$ 时符号处理要细心。",
      "links": [
        "cnt-binom",
        "cnt-term"
      ],
      "book": "选必三",
      "ch": "第6章 计数原理"
