      "keywords": [
        "直线系",
        "圆系",
        "恒过定点",
        "公共弦",
        "待定参数"
      ],
      "content": "**定义/概念**\n具有同一性质的直线的全体叫直线系(族),圆的类似集合叫圆系。常见直线系:①过定点 $(x_{0},y_{0})$:$y-y_{0}=k(x-x_{0})$(缺斜率不存在的直线)或 $A(x-x_{0})+B(y-y_{0})=0$(补全形式);②与 $Ax+By+C=0$ 平行:$Ax+By+\\lambda=0$;③与它垂直:$Bx-Ay+\\lambda=0$(把 $A$、$B$ 互换并变号);④过两直线 $l_{1}:A_{1}x+B_{1}y+C_{1}=0$、$l_{2}:A_{2}x+B_{2}y+C_{2}=0$ 交点:$(A_{1}x+B_{1}y+C_{1})+\\lambda(A_{2}x+B_{2}y+C_{2})=0$。圆系:过两圆 $C_{1}$、$C_{2}$ 交点的圆 $C_{1}+\\lambda C_{2}=0$($\\lambda\\neq-1$);过圆 $C$ 与直线 $l$ 交点的圆系 $C+\\lambda l=0$。\n**核心公式**\n“含参曲线恒过定点”的判定:把方程按参数 $\\lambda$ 整理为 $f(x,y)+\\lambda g(x,y)=0$,它要对任意 $\\lambda$ 都成立,等价于 $f(x,y)=0$ 与 $g(x,y)=0$ 同时成立,联立解出定点。过两直线交点的直线系中 $\\lambda\\to\\infty$ 对应 $l_{2}$ 本身,故该系不含 $l_{2}$;圆系中 $\\lambda=0$ 对应 $C_{1}$,取 $\\lambda=-1$ 时若两圆相交即得公共弦所在直线(二次项抵消),这正是“两圆相减得公共弦”的由来。\n**方法/思路**\n遇到“过两直线交点”“过两圆交点”的曲线,直接设相应系,用题目给的第三个条件定 $\\lambda$,可免去解交点坐标。判断含参直线与圆的位置关系:先找直线恒过的定点,若定点在圆内则直线必与圆相交,免算判别式;若定点在圆上则还需看斜率。已知“直线恒过圆内点”是小题中快速判断相交的常用结论。\n**常考题型与考法**\n①求含参直线(圆)恒过的定点坐标:整理参数法,答案常为具体点;②过两直线交点且满足某条件的直线:设系→代条件→定 $\\lambda$;③与已知直线平行或垂直的直线系设式求参(平行设 $Ax+By+\\lambda=0$,垂直设 $Bx-Ay+\\lambda=0$);④过两圆交点的圆:圆系法,并补验答案恰为 $C_{2}$ 的情形;⑤“直线恒过圆内点”秒判相交的小题;⑥求过两圆交点或圆与直线交点的圆与坐标轴相切等条件;⑦含参直线恒过定点后再给一个位置条件(如与某直线垂直或过另一点),可唯一确定这条直线。\n**易错提示**\n点斜式直线系漏竖直线 $x=x_{0}$,用 $A(x-x_{0})+B(y-y_{0})=0$ 可一次覆盖;直线系 $l_{1}+\\lambda l_{2}=0$ 不含 $l_{2}$,若答案为 $l_{2}$ 需单独验证;圆系要求 $\\lambda\\neq-1$,且 $\\lambda=0$ 对应 $C_{1}$;整理含参方程时各项(含常数项)都要按 $\\lambda$ 归并,勿漏条件个数;两圆方程相减前先化为同系数。",
