      "content": "**定义**:指数幂运算与对数运算是化简求值、解指对方程、比较大小的计算工具,对应讲义第09、10讲及举一反三专题4.1、4.3。\n**核心公式与性质**:幂运算($a>0$, $b>0$):$$a^{r}\\cdot a^{s}=a^{r+s},\\quad (a^{r})^{s}=a^{rs},\\quad (ab)^{r}=a^{r}b^{r}$$ 分数指数幂 $a^{\\frac{m}{n}}=\\sqrt[n]{a^{m}}$($m,n\\in N^{*}$, $n>1$);根式 $\\left(\\sqrt[n]{a}\\right)^{n}=a$,$n$ 为偶数时 $\\sqrt[n]{a^{n}}=|a|$。对数($a>0$ 且 $a\\neq 1$, $M>0$, $N>0$):$$\\log_{a}(MN)=\\log_{a}M+\\log_{a}N$$ $$\\log_{a}\\frac{M}{N}=\\log_{a}M-\\log_{a}N$$ $$\\log_{a}M^{n}=n\\log_{a}M$$ 换底公式 $\\log_{a}b=\\frac{\\log_{c}b}{\\log_{c}a}$,推论 $\\log_{a}b=\\frac{1}{\\log_{b}a}$;对数恒等式 $a^{\\log_{a}N}=N$;$\\log_{a}1=0$、$\\log_{a}a=1$。$\\lg$ 是以 10 为底,$\\ln$ 是以 $e$(约 2.71828)为底的自然对数,$\\ln e=1$。\n**方法/思路**:①化简求值:先化同底再合并;根式改分数指数统一运算;②换底:混合底数的式子选 $\\lg$ 或 $\\ln$ 统一;③指对互化 $a^{x}=N$ ⇔ $x=\\log_{a}N$,用于解简单方程;④解指数/对数方程:化同底或换元(令 $t=a^{x}>0$、$t=\\log_{a}x$),解后回代验根。\n**常考题型与考法**:①化简求值填空(讲义考点一):如 $2^{\\log_{2}3}+\\lg2+\\lg5$ 及混合幂指化简,要求算得快且准;②用换底公式与对数性质表示条件式:已知 $\\log_{a}2=m$、$\\log_{a}3=n$,用 $m$、$n$ 表示 $\\log_{a}12$ 等;③指数方程(如 $4^{x}-2^{x}-2=0$ 型换元)与对数方程(注意真数大于 0 验根);④指数幂比较大小与运算结合的小题。\n**易错提示**:$\\log_{a}(M+N)$ 不能拆成两项,运算律只对乘、除、幂成立;换底公式的底要全程一致;分数指数幂在底数为负且指数分母为偶数时无意义;化简 $\\sqrt{a^{2}}$ 得 $|a|$,勿直接写 $a$。",
