      "content": "**定义/概念** 判定三角形形状与讨论“已知两边及一边对角”时解的个数，本质都是边角互化——把条件统一成只含边或只含角的形式后作等价变形。\n**核心公式/性质** 化边为角：$a=2R\\sin A$，$b=2R\\sin B$，$c=2R\\sin C$；化角为边：$\\sin A=\\frac{a}{2R}$，$\\cos A=\\frac{b^{2}+c^{2}-a^{2}}{2bc}$。判定：\n$$a^{2}+b^{2}=c^{2}\\ (c\\ \\text{最大})\\Rightarrow\\text{直角三角形}$$\n$$c^{2}>a^{2}+b^{2}\\Rightarrow\\text{钝角三角形}$$\n解的个数：由正弦定理 $\\sin B=\\frac{b\\sin A}{a}$：$\\frac{b\\sin A}{a}>1$ 无解，$=1$ 一解（$B=90^{\\circ}$），$<1$ 时两个候选角 $B_{1}$、$B_{2}=\\pi-B_{1}$ 逐个检验 $A+B<180^{\\circ}$ 是否成立。\n**方法/思路** 形状判定：把条件化边为角或化角为边 → 化简到只含单一变量 → 由相等或不等关系下结论；处理 $\\sin2A=\\sin2B$ 时必须保留 $2A=2B$ 与 $2A+2B=\\pi$ 两类。解的个数：优先用“算出 $\\sin B$ 后与 1 比较”的正弦法；几何速判（$A$ 为锐角且 $a<b$ 时）比较 $a$ 与 $b\\sin A$；也可把余弦定理写成关于第三边的一元二次方程，用判别式与正根个数判断，思路最统一。\n**常考题型与考法** ①形状判定小题：给 $a\\cos A=b\\cos B$（或 $\\frac{\\cos A}{\\cos B}=\\frac{b}{a}$ 类）判形状——化边为角得 $\\sin A\\cos A=\\sin B\\cos B$，即 $\\sin2A=\\sin2B$，结论是“等腰或直角三角形”，只写“等腰”即漏解失分。②解答题第(1)问：证明或判定三角形形状，第(2)问据此求边、面积或范围——先化简题给等式到可判定形式，按“由……得 $A=B$，故为等腰三角形”完整书写；由 $\\sin2A=\\sin2B$ 得 $A+B=\\frac{\\pi}{2}$ 的分支也要写。③解的个数选择：问“已知 $a,b,A$ 时三角形有几解”或判断某个解是否成立——分段比较 $a$ 与 $b\\sin A$（或作图数交点）快速作答。④已知三角形类型求边长参数范围（三边 $2,5,x$ 组成锐角三角形）：既要满足“两边差 $<$ 第三边 $<$ 两边和”，又要对最大边验证平方和关系（锐角取小于）。\n**易错提示** ①$\\sin2A=\\sin2B$ 漏掉 $A+B=\\frac{\\pi}{2}$ 这一类是形状题最常见的失分点。②判钝角、直角必须找最大边来比较平方。③“等腰或直角”等并列结论要写全。④“锐角三角形”要求三个内角都锐（等价于三条边的平方两两满足余弦为正），只检验最大角不够。",
