      "content": "**定义/概念**\n求导后令 $f'(x)=0$,若这个方程是超越方程(含 $e^{x}$、$\\ln x$ 与多项式混合)而无法解出精确根,但由零点存在定理能确定根存在且唯一,这样的根称为**隐零点**,记作 $x_{0}$。\n**核心公式**\n隐零点 $x_{0}$ 满足 $f'(x_{0})=0$,即得到一个可用来自我代换的等式(例如 $e^{x_{0}}=\\frac{1}{x_{0}}$ 或 $\\ln x_{0}=-x_{0}$);把最值 $f(x_{0})$ 中的超越项用这个等式替换掉,通常能化成一个简单的代数式。\n**方法/思路**\n①求导并判断 $f'(x)$ 的单调性(通常再求一次导),说明 $f'(x)=0$ 有唯一根;②用零点存在定理把 $x_{0}$ 夹在相邻整数之间(如 $x_{0}\\in(1,2)$);③由 $f'(x_{0})=0$ 写出代换关系,化简 $f(x_{0})$;④由 $x_{0}$ 的取值范围对化简结果放缩,得到最值的范围或证明所需不等式。\n**常考题型与考法**\n①求函数在给定区间上的最值(精确值不可得,只需范围);②证明 $f(x)\\geq 0$ 恒成立(转化为 $f(x)_{\\min}\\geq 0$);③讨论零点个数或方程根的个数;④证明含 $e^{x}$、$\\ln x$ 的不等式。\n**易错提示**\n只说“存在 $x_{0}$”却不给出所在区间,导致后面的放缩无依据;代换时把 $f'(x_{0})=0$ 用反(把 $x_{0}$ 代成 $e^{x_{0}}$ 的方向要选能消去超越项的那一边);放缩过头使结论失效;忘记说明 $f'(x)$ 单调(否则“唯一根”不成立)。",
