      "content": "**定义/概念**\n把“直线与圆锥曲线联立”后的二次方程系数、判别式、韦达定理与弦长写成固定形式,考场直接套用的一类记忆型二级结论,俗称硬解定理。它的价值在于**省去每次联立的重复计算**,但前提是系数必须记准。\n**核心公式**\n以椭圆 $\\frac{x^{2}}{a^{2}}+\\frac{y^{2}}{b^{2}}=1$ 与直线 $Ax+By+C=0$ 为例,联立消 $y$ 得\n$$(a^{2}A^{2}+b^{2}B^{2})x^{2}+2a^{2}AC\\,x+a^{2}(C^{2}-b^{2}B^{2})=0$$\n于是 $x_{1}+x_{2}=-\\frac{2a^{2}AC}{a^{2}A^{2}+b^{2}B^{2}}$,$x_{1}x_{2}=\\frac{a^{2}(C^{2}-b^{2}B^{2})}{a^{2}A^{2}+b^{2}B^{2}}$;弦长用统一的\n$$|AB|=\\sqrt{1+k^{2}}\\,|x_{1}-x_{2}|=\\sqrt{1+\\frac{1}{k^{2}}}\\,|y_{1}-y_{2}|$$\n计算(后一个式子用于斜率可能不存在或很大的情形)。\n**方法/思路**\n①先把直线写成一般式 $Ax+By+C=0$,与标准方程对齐系数;②按上面的结构直接写出 $x_{1}+x_{2}$、$x_{1}x_{2}$;③遇到定值、定点、弦长、面积问题,把韦达结果整体代入,避免展开判别式;④**记不准时果断放弃套公式,老老实实联立**——算对比算快重要。\n**常考题型与考法**\n①弦长问题;②三角形面积(弦长×点到直线距离÷2);③证明某量为定值(把韦达式代入后 $a$、$b$、$A$、$B$、$C$ 相互抵消);④直线过定点;⑤与向量条件(如 $\\vec{OA}\\cdot\\vec{OB}=0$)结合。\n**易错提示**\n公式里 $a^{2}A^{2}$ 与 $b^{2}B^{2}$ 的位置记反(这是最常见的错误,建议每次默写一遍);忘记讨论直线斜率不存在的情形;求面积时把弦长与高弄混;得到定点/定值结论后不做必要的范围检验。",
