      "content": "**定义/概念**\n椭圆(或双曲线)上一点 $P$ 与两个焦点 $F_{1}$、$F_{2}$ 构成的三角形 $\\triangle PF_{1}F_{2}$ 称为焦点三角形。它是把“定义”与“解三角形”结合起来的核心模型。\n**核心公式**\n记 $\\theta=\\angle F_{1}PF_{2}$。\n椭圆:$|PF_{1}|+|PF_{2}|=2a$,由余弦定理 $|F_{1}F_{2}|^{2}=|PF_{1}|^{2}+|PF_{2}|^{2}-2|PF_{1}||PF_{2}|\\cos\\theta$ 可解得 $|PF_{1}||PF_{2}|=\\frac{2b^{2}}{1+\\cos\\theta}$,面积 $S=b^{2}\\tan\\frac{\\theta}{2}$;当 $P$ 在短轴端点时 $\\theta$ 最大、面积最大。\n双曲线:$\\bigl||PF_{1}|-|PF_{2}|\\bigr|=2a$,面积 $S=\\frac{b^{2}}{\\tan\\frac{\\theta}{2}}=b^{2}\\cot\\frac{\\theta}{2}$。\n**方法/思路**\n①看到焦点三角形先写定义式(椭圆写“和”,双曲线写“差”);②配余弦定理建立 $|PF_{1}|$、$|PF_{2}|$ 的方程;③求离心率时把得到的边长关系整理成关于 $a$、$c$ 的齐次式,再同除以 $a$ 的最高次幂;④求最值时用 $a-c\\leq|PF|\\leq a+c$。\n**常考题型与考法**\n①求焦点三角形面积;②求离心率(高频,常与 $\\angle F_{1}PF_{2}=90^{\\circ}$、$|PF_{1}|=2|PF_{2}|$ 等条件结合);③求 $\\triangle PF_{1}F_{2}$ 的周长(椭圆中恒为 $2a+2c$);④与正弦定理结合求角。\n**易错提示**\n椭圆用“和”、双曲线用“差”,用错则面积公式全错;面积公式中的角必须是 $\\angle F_{1}PF_{2}$(顶点在 $P$),不是焦点处的角;双曲线要注意 $P$ 在哪一支(决定差的符号);用余弦定理时把 $|F_{1}F_{2}|=2c$ 写成 $c$。",
