      "content": "**定义/概念**\n形如 $(x-a_{1})(x-a_{2})\\cdots(x-a_{n})>0$(或 $<0$)的不等式称为高次不等式,用**数轴穿根法**(根轴法)求解最方便。\n**方法/思路**\n①把不等式整理成一边为 0、另一边已因式分解的形式,**并把最高次项系数化为正**;②求出所有根并在数轴上标出;③从最右端的上方开始,自右向左画线:遇到**奇次根穿过**数轴,**偶次根折返不穿**(口诀“奇穿偶不穿”);④按“大于 0 取数轴上方、小于 0 取下方”写出解集,注意端点取舍($>$ 取空心, $\\geq$ 取实心)。\n**常考题型与考法**\n①解 $(x-1)(x-2)(x-3)>0$ 一类标准型;②含重根的(如 $(x-1)^{2}(x-2)>0$,在 $x=1$ 处不穿);③分式不等式先移项通分化为整式高次不等式(切忌直接两边乘分母);④与函数单调性、导数符号表结合。\n**易错提示**\n忘记先把最高次项系数化为正(否则“上方/下方”判断全反);把偶次根也画成穿过;分式不等式两边同乘分母(分母符号未知,必须移项通分);把端点一律写成实心或一律写成空心;重根处误判符号。",
